Semaphore mutex, empty, full;
mutex=1; //互斥信号量，初始无人操作邮箱
empty=N; //初始信箱无邮件
full=0;
Writer() { //发邮件
    wait(mutex); if(full==N) wait(full);
    Send(); //发邮件
    full++; signal(mutex); signal(empty); //空邮件减少
}
Reader() { //读邮件
    wait(mutex); if(empty==0); wait(empty);
    Reacl(); //读邮件
    empty++; signal(mutex); signal(full); //邮件减少
}
